    sigma = B.m[0][0] + B.m[1][1] + B.m[2][2];
    z[0] = B.m[1][2] - B.m[2][1];
    z[1] = B.m[2][0] - B.m[0][2];
    z[2] = B.m[0][1] - B.m[1][0];

    K[0][0] = sigma;
    for (i = 0; i < 3; i++) {
        K[0][i + 1] = z[i];
        K[i + 1][0] = z[i];
        for (j = 0; j < 3; j++) {
            K[i + 1][j + 1] = B.m[i][j] + B.m[j][i] - ((i == j) ? sigma : 0.0);
        }
    }

    /* Add regularization term to diagonal */
    for (i = 0; i < 4; i++) {
        K[i][i] += 3.0 * weight_sum;
    }

    /* Power iteration to find principal eigenvector */
    for (iter = 0; iter < 64U; iter++) {
        nrm = 0.0;
        for (i = 0; i < 4; i++) {
            next[i] = 0.0;
            for (j = 0; j < 4; j++) {
                next[i] += K[i][j] * v[j];
            }
            nrm += next[i] * next[i];
        }
        nrm = sqrt(nrm);

        if (nrm <= ADCS_EPS_NORM) {
            *out = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
            return ADCS_E_DEGENERATE;
        }

        diff = 0.0;
        for (i = 0; i < 4; i++) {
            next[i] /= nrm;
            diff += fabs(next[i] - v[i]);
            v[i] = next[i];
        }

        if (diff < 1.0e-13) {
            break;
        }
    }

    /* Assign result */
    *out = (adcs_quat_t){v[0], v[1], v[2], v[3]};

    /* Canonicalize w >= 0 */
    if (out->w < 0.0) {
        out->w = -out->w;
        out->x = -out->x;
        out->y = -out->y;
        out->z = -out->z;
    }

    /* Check convergence */
    if (iter >= 64U) {
        return ADCS_E_NO_CONVERGENCE;
    }

    return ADCS_OK;
}

